---@type table<number, table>
local Orders = {}
---@type table<number, string[]>
local Billings = {}
local CashBillings = {}

OrderManager = {}

function OrderManager.pushOrderCache(order)
    Orders[order.orderId] = order
end

function OrderManager.consumeOrder(userId, subKey)
    local removes = {}
    for orderId, order in pairs(Orders) do
        if order.userId == userId and order.subKey == subKey then
            EngineUtil.disposePlatformOrder(userId, orderId, true)
            table.insert(removes, orderId)
        end
    end
    for _, orderId in pairs(removes) do
        Orders[orderId] = nil
    end
    if PlayerManager:getPlayerByUserId(userId) == nil then
        ---玩家已经存完数据，但玩家已经提前退出游戏了，需要把这段时间产生的订单都上报为成功发货
        OrderManager.reportBilling(userId)
    end
end

function OrderManager.restoreOrder(userId, subKey)
    local removes = {}
    for orderId, order in pairs(Orders) do
        if order.userId == userId and order.subKey == subKey then
            EngineUtil.disposePlatformOrder(userId, orderId, false)
            table.insert(removes, orderId)
        end
    end
    for _, orderId in pairs(removes) do
        Orders[orderId] = nil
    end
end

---添加游戏订单
function OrderManager.addGameBilling(userId, orderId)
    userId = tonumber(userId)
    local billings = Billings[userId] or {}
    table.insert(billings, orderId)
    Billings[userId] = billings
end

---上报成功调用存储的游戏订单
function OrderManager.reportBilling(userId)
    userId = tonumber(userId)
    local billings = Billings[userId] or {}
    if next(billings) == nil then
        return
    end
    WebService:ReportGameBilling(userId, billings)
    Billings[userId] = nil
end

---添加游戏内现金支付订单
function OrderManager.addGameCashBillings(userId, orderId)
    userId = tonumber(userId)
    local billings = CashBillings[userId] or {}
    table.insert(billings, orderId)
    CashBillings[userId] = billings
end

---上报成功调用存储的游戏现金支付订单
function OrderManager.reportCashBillings(userId)
    userId = tonumber(userId)
    local billings = CashBillings[userId] or {}
    if next(billings) == nil then
        return
    end
    WebService:ReportGameCashBilling(userId, billings)
    CashBillings[userId] = nil
end

return OrderManager